{
  "findings": [
    {
      "ref": "[D526]",
      "area": "data",
      "claim": "A parent reports that Roblox collects personal data from children under 13 without parental consent.",
      "stance": "risk",
      "quote": "Apple is also accused of knowingly allowing developers to collect personal data from children under 13 without parental consent, despite having actual knowledge of the user’s age."
    },
    {
      "ref": "[D526]",
      "area": "money",
      "claim": "A parent reports that Roblox allows unauthorized in-app purchases by children without proper parental consent.",
      "stance": "risk",
      "quote": "Apple continues to allow teens over 13 to make purchases without linking to a parent account, and parental controls are underutilized or unreliable, leaving most children ages 13–17 and many under 13 able to spend without approval."
    },
    {
      "ref": "[D526]",
      "area": "contact",
      "claim": "A parent reports that Roblox allows strangers to message or voice chat with children, and this feature can be turned off.",
      "stance": "risk",
      "quote": "On Roblox, parents must create a parent account, verify their age, link it to the child’s account and dig through menus to manage content, chat, servers spending and screen time."
    },
    {
      "ref": "[D526]",
      "area": "age_gating",
      "claim": "A parent reports that Roblox’s age gating does not work in practice, as children can enter any birthdate before September 2007 to bypass restrictions.",
      "stance": "risk",
      "quote": "A kid who wants to dodge all of the above can simply enter any birthdate before September 2007."
    },
    {
      "ref": "[D526]",
      "area": "content",
      "claim": "A parent reports that Roblox contains user-generated content that may be inappropriate for children, including violent or sexual themes.",
      "stance": "neutral",
      "quote": "The complaint alleges that Apple’s app rating process is inadequate and deceptive, relying on developers’ self-reported answers without fully assessing harmful content."
    }
  ]
}
